use super::*;

pub(crate) fn language_for(tech: &str) -> Option<tree_sitter::Language> {
    match tech {
        "rust" => Some(tree_sitter_rust::LANGUAGE.into()),
        // TypeScript classification is intentionally out of scope for the first version: the store holds
        // 32 Rust records against thousands of Rust functions, and the maintainer's decomposition target
        // is the Rust side. A `tsx`/`ts` arm can ride the same shape later.
        _ => None,
    }
}
